INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 0, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1355","leftImageAlt":"img1355","html":"The 🛩️ touched down in 📌<a href=\"https://en.wikipedia.org/wiki/Port_of_Spain\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Port of Spain</a> just before noon. We hailed a 🚕taxi to our hotel, <a href=\"https://expedia.com/affiliate/Zm1VD21\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">The BRIX, Autograph Collection</a>. We selected this 🏨for its upscale accommodations, great deal, and proximity to key attractions like 📌<a href=\"https://en.wikipedia.org/wiki/Queen%27s_Park_Savannah\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Queen's Park</a>."}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 1, $s$itinerary_with_map$s$, $s${"itineraryId":"00102543-0245-4675-b82d-c53ff19ef89c"}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 2, $s$text$s$, $s${"html":"We strolled down the street, passing the historic  📌<a href=\"https://queenshalltt.com/\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Queen's Hall</a>, heading towards the 📌<a href=\"https://visittrinidad.tt/blog/magnificent-seven-in-port-of-spain-trinidad/\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Magnificent Seven</a>, a collection of seven stunning Victorian-era mansions on Maraval Road in #PortofSpain. These 🏰architectural gems, built between 1902 and 1910, offer a glimpse into the island's opulent past. We strolled along the street, admiring their unique architectural styles, including French Colonial, Scottish baronial, and Indian Empire influences"}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 3, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1327","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1325","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1333","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1329","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1320","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1342","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1337"]}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 4, $s$two_column$s$, $s${"leftType":"text","rightType":"image","rightImage":"aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1354","rightImageAlt":"img1354","html":"As we strolled through 📌<a href=\"https://en.wikipedia.org/wiki/Memorial_Park,_Port_of_Spain\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Memorial Park</a> and the iconic 📌<a href=\"https://en.wikipedia.org/wiki/Queen%27s_Park_Oval\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Queen's Park Oval</a>, we couldn’t resist indulging in this cold, refreshing 🥥coconut water from street vendors."}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 5, $s$text$s$, $s${"html":"As it was still early afternoon, we hopped into a 🚕, heading downtown to the vibrant soul, a blend of history and culture. Downtown Port of Spain is a whirlwind of activity. Historic landmarks stand proudly alongside modern buildings while the air is filled with the sounds of lively chatter, music, and the tempting aromas of street food. It’s a captivating blend of history and modernity with grand colonial buildings, bustling markets, and squares."}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 6, $s$itinerary_with_map$s$, $s${"itineraryId":"8e450746-9475-44b0-8217-5a94fa6cc12a"}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 7, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1372","leftImageAlt":"img1372","html":"We asked the driver to drop us off a few blocks from 📌<a href=\"https://en.wikipedia.org/wiki/Independence_Square_(Port_of_Spain\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Independence Square</a>), so we could soak in the vibrant atmosphere of downtown.  Independence Square was a bustling hub of activity, with people going about their day and street vendors selling their wares. We wandered through the square, soaking up the vibrant atmosphere and admiring the architecture of the surrounding buildings."}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 8, $s$text$s$, $s${"html":"Towering government buildings watched over the square. We passed the Houses of Parliament, a grand building with a political history. The Supreme Court, a majestic edifice, stood nearby, a reminder of the island's legal system. It was a fascinating walk, a journey through the heart of Trinidad and Tobago's governance. The square pulsed with the vibrant energy of this Caribbean capital, surrounded by historic government buildings. We approached the majestic 📌<a href=\"https://en.wikipedia.org/wiki/Cathedral_of_the_Immaculate_Conception_(Port_of_Spain\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Cathedral of the Immaculate Conception⛪</a>), which loomed against the lively Port of Spain skyline. Stepping inside was like entering another world of inspiring beauty. Sunlight streamed through stained glass windows, casting colors across the polished marble floor. \nWe were drawn into the lively market, a sensory explosion! We navigated the bustling crowds, captivated by the vibrant display of fruits and vegetables. Mountains of pineapples, peppers, and many other colorful produce overflowed from every stall, creating an exhilarating experience that immersed us in the local culture. We continued our exploration, venturing towards 📌<a href=\"https://en.wikipedia.org/wiki/Holy_Trinity_Cathedral,_Port_of_Spain\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Trinity Cathedral⛪</a>, architectural beauty, a breathtaking testament to the island's history. We continued along the road, passing charming gardens adorned with sculptures, until we reached the traffic light where the police station was located; our journey then came to an unexpected halt. A friendly 👮police officer advised us against proceeding further, citing safety concerns for tourists in that particular area."}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 9, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1378","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1380","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1383","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1390","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1392","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1399","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1404","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1408","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1411","aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1374"]}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 10, $s$text$s$, $s${"html":"Our destination? 📌Ariapita Avenue, renowned as Port of Spain's \"foodie street”. We envisioned a lively culinary scene with many restaurants and some street vendors. Unfortunately, our expectations weren't fully met. The street seemed a bit subdued, with several establishments closed. We weren't sure if the time of day (around 7 PM) or perhaps the off-season (October) contributed to the quieter atmosphere. Hungry, we followed the hotel's recommendation and returned to Memorial Park, eager to sample the local flavors. We paused at the Cenotaph Garden, paying our respects at this poignant memorial within Memorial Park."}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 11, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1422","leftImageAlt":"img1422","html":"We were excited to discover a vibrant food truck scene, a delicious and lively way to experience the local cuisine at the southern point of the park, across from the performance art center.  It was the perfect place to experience authentic local cuisine."}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 12, $s$two_column$s$, $s${"leftType":"text","rightType":"image","rightImage":"aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1438","rightImageAlt":"img1438","html":"Back at the hotel, we retreated to the rooftop 🍻bar. Sipping on cool drinks🍹, we relaxed and enjoyed breathtaking panoramic views of the city sparkling below."}$s$::jsonb),
  ($s$1cba051d-8a5b-409a-b32f-2c62ec6fc1c7$s$, 13, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/trinidad-and-tobago/1/IMG_1433","leftImageAlt":"img1433","html":"A delightful surprise awaited us in our room! A beautifully arranged tray laden with decadent cakes sat on the table, a thoughtful gesture from the hotel to celebrate my husband's birthday and our anniversary. What a wonderful way to end the day!"}$s$::jsonb);
INSERT INTO "blog_posts" ("id", "country_slug", "post_index", "country", "country_code", "state", "title", "subtitle", "header", "description", "excerpt", "background_image", "tips_cta_copy", "tips_slug", "status", "published_at", "created_at") VALUES ($s$f7283f99-3eaf-4272-af7c-e78d55ea7b1b$s$, $s$united-states-connecticut$s$, 1, $s$United States$s$, $s$US$s$, $s$Connecticut$s$, $s$📍Mystic, Just a Quick, But Memorable, Pause! ⏳📸$s$, $s$Uncovering Coastal Charm & Maritime Magic! ✨⚓$s$, $s$📍Mystic, Connecticut$s$, $s$Discovering Mystic: A Charming Detour on the Way to Providence. Did you know that the Mystic River Bascule Bridge, which you'll likely cross while driving through Mystic, opens on average 2,200 times yearly? That's almost six times a day!$s$, $s$Our Enchanting Stop in Mystic, CT! ⚓🍕✨$s$, $s$aroundtheworld50s/blog/united-states-connecticut/1/IMG_0018$s$, $s$💥 New England - Insider Tips ⁉️: Your Key to an Unforgettable Trip (read more...)$s$, $s$united-states-connecticut$s$, $s$published$s$, '2025-07-13T00:00:00.000Z'::timestamptz, '2025-07-13T00:00:00.000Z'::timestamptz);
INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$f7283f99-3eaf-4272-af7c-e78d55ea7b1b$s$, 0, $s$text$s$, $s${"html":"On our journey north, a spontaneous, we made a detour led us to the enchanting coastal town of Mystic, Connecticut! Don't let \"quick stop\" fool you – this place isn't just a dot on the map; it's a vibrant tapestry of history, marine life, and undeniable New England charm, making it the perfect, enriching interlude on any road trip.\n\nWe stopped at the 📌 Hoxie Scenic Overlook for breathtaking views, to capture the panoramic vista of the Mystic River, the iconic Bascule Bridge, the sprawling Mystic Seaport Museum, and the quaint, historic village nestled along the water. It's the absolute perfect spot to capture that postcard-perfect photo of this charming New England town. 📸\n\nWhile its fame might be tied to \"Mystic Pizza\" 🍕 (and yes, you absolutely should grab a slice – it's a rite of passage!), the town offers so much more profound insight into its maritime soul.\n\nThe Mystic River flows right through the heart of it. The star attraction here is undoubtedly the Mystic Bascule Bridge. Don't just walk over it – wait for it to lift! Watching this historic drawbridge gracefully rise to let tall ships and pleasure boats pass. The streets themselves are a delight, lined with independent boutiques, art galleries showcasing local talent, and cozy cafes. It's the perfect place to browse for unique souvenirs, grab a coffee, and just soak in the laid-back, nautical atmosphere.\nAlthough we didn't visit the famous Mystic Seaport Museum this time, I highly recommend setting aside a couple of hours for it, as we had an incredible experience on a previous occasion. It's an immersive living history village with historic ships. ⛵🕰️ Or, if you're traveling with kids, the Mystic Aquarium is a fantastic option (💥you can often buy a combined ticket for both attractions!). Kids especially love seeing the beluga whales and other marine life up close! 🐳🐠"}$s$::jsonb),
  ($s$f7283f99-3eaf-4272-af7c-e78d55ea7b1b$s$, 1, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-connecticut/1/IMG_0016","aroundtheworld50s/blog/united-states-connecticut/1/IMG_0019","aroundtheworld50s/blog/united-states-connecticut/1/IMG_0018","aroundtheworld50s/blog/united-states-connecticut/1/IMG_9878","aroundtheworld50s/blog/united-states-connecticut/1/IMG_9879","aroundtheworld50s/blog/united-states-connecticut/1/IMG_9877","aroundtheworld50s/blog/united-states-connecticut/1/IMG_9876"]}$s$::jsonb);
