INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 0, $s$itinerary_with_map$s$, $s${"itineraryId":"2f41e232-45e0-4de1-9f8c-6f7baab4cf61"}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 1, $s$text$s$, $s${"html":"Our long weekend adventure started with a stay at the 🏨 <a href=\"https://expedia.com/affiliate/RF52NY3\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Hilton Providence</a>, perfectly situated for exploring the city. We chose this location strategically, allowing us to easily walk to key attractions during the day and immerse ourselves in the vibrant nightlife of Federal Hill in the evenings.\n\nAfter a 14-minute walk, we approached the first POI on our list, the 📌<a href=\"https://en.wikipedia.org/wiki/Rhode_Island_State_House\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Rhode Island State House</a>. As we approached, its majestic presence dominated the skyline. Perched on a hill, this impressive building is a landmark visible from afar. Its grandeur is undeniable, particularly the sweeping staircase that adds to its imposing stature."}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 2, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0027","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0029","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0031","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0023"]}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 3, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0028","leftImageAlt":"img0028","html":"From the State House, a leisurely four-minute stroll brought us to 📌<a href=\"https://en.wikipedia.org/wiki/Providence_station\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Station Park</a>, a charming green space surrounding the Providence Station. The 🚉station is a magnificent architectural feat, blending Victorian Gothic and Romanesque Revival styles."}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 4, $s$two_column$s$, $s${"leftType":"text","rightType":"image","rightImage":"aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0026","rightImageAlt":"img0026","html":"Next, we made our way to 📌<a href=\"https://en.wikipedia.org/wiki/Waterplace_Park\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Waterplace Park</a>, a stunning urban oasis overlooking the Providence River. The park boasts a cascading waterfall, making it a perfect spot to relax and enjoy the city views."}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 5, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0038","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0024"]}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 6, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0041","leftImageAlt":"img0041","html":"Did you know that Providence boasts its own 📌<a href=\"https://www.visitrhodeisland.com/listing/independence-trails-providence/10068/\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Independence Trail</a>?\n\nStep into History: Following Providence's Independence Trail! 📜🚶‍♀️🇺🇸\nLace up your walking shoes!\n In Providence, we didn't just read about history – we walked right through it on the Independence Trail! This self-guided journey through the city's historic core reveals fascinating stories of the Revolutionary War, colonial architecture, and pivotal moments that shaped America's fight for freedom. It's a captivating way to connect with the past, one historic step at a time. ✨"}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 7, $s$two_column$s$, $s${"leftType":"text","rightType":"image","rightImage":"aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0060","rightImageAlt":"img0060","html":"We followed this historic path, leading us to 📌Alex and Ani City Center, where a lively atmosphere was already building as people gathered for the 4th of July evening festivities."}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 8, $s$text$s$, $s${"html":"The trail weaves through this iconic street. Each building tells a story, offering a picturesque journey through centuries of Providence's past. 🏘️\n\nWe passed by the renowned 📌Trinity Brewery along the way.\nWhile Trinity Brewhouse is a fantastic and historic local brewery (established in 1994, it's one of New England's first brewpubs!), it doesn't fall within the historical period covered by the Independence Trail, which focuses on colonial and Revolutionary War-era sites. However, it's a great spot to grab a craft beer and a bite to eat if you're exploring downtown Providence after your historical walk! 🍻"}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 9, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0057","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0061"]}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 10, $s$text$s$, $s${"html":"Our journey continued towards 📌<a href=\"https://en.wikipedia.org/wiki/Brown_University\" class=\"post-link\" target=\"_blank\"rel=\"noopener noreferrer\">Brown University</a>. \n\nStrolling to Scholarship: Brown University Bound! 🎓🌳✨\nFrom the grandeur of Memorial Boulevard, we took a picturesque walk up to Brown University! 🚶‍♀️\nThis historic campus, nestled on College Hill, offers stunning architecture, vibrant student life, and a sense of intellectual energy. \nIt's a beautiful stroll from downtown, connecting the city's urban pulse with its academic heart. ❤️ \n📌<a href=\"https://en.wikipedia.org/wiki/File:Providence_RI_-_Memorial_Blvd_-_Omni_Hotel_Skywalk.jpg\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Memorial Boulevard</a>, lined with impressive historic buildings, led us up 📌<a href=\"https://en.wikipedia.org/wiki/College_Hill,_Providence,_Rhode_Island\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">College Hill</a> towards the iconic Brown University Tower. The campus buzzed with energy, with students mingling amongst outdoor sculptures, creating a vibrant and youthful atmosphere."}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 11, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0047","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0046","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0049","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0050","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0052","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0053"]}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 12, $s$text$s$, $s${"html":"For dinner, we ventured into the vibrant 📌<a href=\"https://en.wikipedia.org/wiki/Federal_Hill,_Providence,_Rhode_Island\" class=\"post-link\" target=\"_blank\" rel=\"noopener noreferrer\">Federal Hill</a> neighborhood, a bustling enclave of Italian-American heritage. Walking down the charming streets, lined with cozy restaurants and lively bars, we were captivated by the lively atmosphere. We chose to dine at one of the many outdoor spaces, enjoying the live music and soaking in the vibrant energy of the neighborhood."}$s$::jsonb),
  ($s$31920ab8-ff00-48d0-a977-56f84d74b1f2$s$, 13, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0069","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0068","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0067","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0066","aroundtheworld50s/blog/united-states-rhode-island/1/IMG_0065"]}$s$::jsonb);
INSERT INTO "blog_posts" ("id", "country_slug", "post_index", "country", "country_code", "state", "title", "subtitle", "header", "description", "excerpt", "background_image", "tips_cta_copy", "tips_slug", "status", "published_at", "created_at") VALUES ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, $s$united-states-massachusetts$s$, 1, $s$United States$s$, $s$US$s$, $s$Massachusetts$s$, $s$📍Plymouth, Massachusetts$s$, $s$Journey to the Past: Unveiling Historic Plymouth, MA! 📜⚓✨$s$, $s$📍Plymouth, Massachusetts -- Where America's Story Begins! 🇺🇸$s$, $s$Ever wondered what it was really like in 1620? Or how history shaped one of America's most beloved towns? This blog takes you beyond the myths and into the heart of this extraordinary destination. Discover Plymouth, Massachusetts, from the iconic Plymouth Rock🪨 to the living history of Plimoth Patuxet. Join us for a journey back to where it all began.$s$, $s$✨Step Back in Time: Discover Historic Plymouth, MA🚢$s$, $s$aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0296$s$, $s$💥 Insider Tips: Your Key to an Unforgettable Trip to Massachusetts (read more...)$s$, $s$united-states-massachusetts$s$, $s$published$s$, '2025-07-22T00:00:00.000Z'::timestamptz, '2025-07-22T00:00:00.000Z'::timestamptz);
