  ($s$20b67131-0141-4e21-a02b-f0f40ee9c472$s$, 0, $s$📌Lady Young Road Lookup$s$),
  ($s$20b67131-0141-4e21-a02b-f0f40ee9c472$s$, 1, $s$📌San Juan$s$),
