INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$79a07569-e9bd-4535-8e4e-df7e06c99d5a$s$, 0, $s$itinerary_with_map$s$, $s${"itineraryId":"20b67131-0141-4e21-a02b-f0f40ee9c472"}$s$::jsonb),
  ($s$79a07569-e9bd-4535-8e4e-df7e06c99d5a$s$, 1, $s$text$s$, $s${"html":"Our adventure began with breathtaking views. We ascended 📌Lady Young Road, the panoramic vista from the overlook leaving us speechless. Port of Spain shimmered below. 💥I'd recommend skipping the overpriced fruit stalls at the overlook – the scenery alone is worth the stop. \nNext, we headed towards 📌San Juan, a bustling local market where the aroma of spices and the lively chatter of vendors filled the air. This was the real deal, where locals came to shop for their daily needs. We indulged in the local delicacy, 🫓doubles – a delightful combination of curried chickpeas and bara bread, a good start for the day."}$s$::jsonb),
  ($s$79a07569-e9bd-4535-8e4e-df7e06c99d5a$s$, 2, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1448","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1447","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1444","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1313","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1314","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1312","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1310","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1316"]}$s$::jsonb),
  ($s$79a07569-e9bd-4535-8e4e-df7e06c99d5a$s$, 3, $s$text$s$, $s${"html":"Our next destination: 📌Paria Bay. Anticipation built as we imagined the pristine beach we'd seen in photos. However, our excitement quickly turned to apprehension—the paved road led to a gravel road, then a muddy track. After a grueling 45-minute drive over half a mile of treacherous terrain, we encountered a resident. He warned us that the road deteriorated further, and it could take another 2-3 hours to reach the trailhead, followed by a challenging hike through the mud. We reluctantly decided to turn back."}$s$::jsonb),
  ($s$79a07569-e9bd-4535-8e4e-df7e06c99d5a$s$, 4, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1456","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1462","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1466","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1478"]}$s$::jsonb),
  ($s$79a07569-e9bd-4535-8e4e-df7e06c99d5a$s$, 5, $s$text$s$, $s${"html":"Undeterred, we headed towards 📌Las Cuevas Beach. With its crescent of golden sand and a picturesque backdrop of colorful fishing boats, this secluded paradise felt like a hidden gem. We cautiously entered the water, mindful of the sudden drop-off that lurked beneath the surface.\n💥You might encounter kids offering beach chair and umbrella rentals. They often start with a high asking price, but don't hesitate to negotiate! You can usually settle on a much lower amount."}$s$::jsonb),
  ($s$79a07569-e9bd-4535-8e4e-df7e06c99d5a$s$, 6, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1503","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1504","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1507","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1511","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1512","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1513","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1515"]}$s$::jsonb),
  ($s$79a07569-e9bd-4535-8e4e-df7e06c99d5a$s$, 7, $s$text$s$, $s${"html":"Finally, we arrived at the legendary Maracas Beach, famous for its world-renowned 📌Maracas Bay Beach. We spent the next three hours basking in the sun, simply enjoying the tranquility of this iconic beach. As the sun descended, we reluctantly packed up and headed back, as we wanted to avoid driving after dark! The roads here are incredibly narrow, with no shoulders and steep trenches right alongside, making night driving quite hazardous.\nWe capped off our day with a memorable dining experience. The hotel was participating in Restaurant Week, offering a prix fixe dinner that was a true culinary journey. Be sure to make a reservation, as these special menus are highly sought after. Allow for approximately three hours to fully enjoy the multiple courses and savor each delectable bite."}$s$::jsonb),
  ($s$79a07569-e9bd-4535-8e4e-df7e06c99d5a$s$, 8, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1442","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1443","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1524","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1532","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1535","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1534","aroundtheworld50s/blog/trinidad-and-tobago/2/IMG_1536"]}$s$::jsonb);
INSERT INTO "blog_posts" ("id", "country_slug", "post_index", "country", "country_code", "state", "title", "subtitle", "header", "description", "excerpt", "background_image", "tips_cta_copy", "tips_slug", "status", "published_at", "created_at") VALUES ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, $s$trinidad-and-tobago$s$, 3, $s$Trinidad and Tobago$s$, $s$TT$s$, NULL, $s$✨A West Coast Adventure: A Glimpse of Trinidad's Heartbeat$s$, $s$A West Coast Vibe Adventure! 🇹🇹🎶✨$s$, $s$📍A West Coast Adventure$s$, $s$Today, we embarked on an adventure to explore the heartland of Trinidad, venturing west from the bustling city. The drive along the winding road (the only road) was a journey in itself, passing through charming villages where life moved at a slower pace.$s$, $s$✨A West Coast Adventure✨$s$, $s$aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1737$s$, $s$💥 Insider Tips: Your Key to an Unforgettable Trip (read more...)$s$, $s$trinidad-and-tobago$s$, $s$published$s$, '2025-07-28T00:00:00.000Z'::timestamptz, '2025-07-28T00:00:00.000Z'::timestamptz);
INSERT INTO "blog_itineraries" ("id", "post_id", "position", "title", "map_embed_url") VALUES
  ($s$fb6d7286-acab-4b5a-9b6a-2c7127870958$s$, $s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 0, $s$West Coast Trinidad$s$, $s$https://www.google.com/maps/embed?pb=!1m40!1m12!1m3!1d250998.64716139913!2d-61.44180391187146!3d10.590596775473855!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!4m25!3e0!4m5!1s0x8c3607d0be7ebb55%3A0x2dd4764afb66c4d6!2sThe%20BRIX%2C%20Autograph%20Collection%2C%20Coblentz%20Avenue%2C%20Port%20of%20Spain%2C%20Trinidad%20and%20Tobago!3m2!1d10.6730318!2d-61.5088929!4m5!1s0x8c49ff75c184d3bf%3A0xe3f0aa1c0cd2b39a!2sArima%2C%20Trinidad%20and%20Tobago!3m2!1d10.631941399999999!2d-61.284540899999996!4m5!1s0x8c49f3bc90e33e57%3A0x78dbce4df526b3d1!2sSangre%20Grande%20Regional%20Corporation%2C%20Trinidad%20and%20Tobago!3m2!1d10.6446884!2d-61.0937206!4m5!1s0x8c4a1959d9072d83%3A0x90b90eb387e28762!2sManzanilla%20Beach%2C%20Manzanilla%20Mayaro%20Road%2C%20Lower%20Manzanilla%2C%20Trinidad%20and%20Tobago!3m2!1d10.508058199999999!2d-61.0435229!5e0!3m2!1sen!2sus!4v1753758304605!5m2!1sen!2sus$s$);
INSERT INTO "blog_itinerary_items" ("itinerary_id", "position", "content") VALUES
  ($s$fb6d7286-acab-4b5a-9b6a-2c7127870958$s$, 0, $s$📍Arima$s$),
  ($s$fb6d7286-acab-4b5a-9b6a-2c7127870958$s$, 1, $s$📍Sangre Grande$s$),
  ($s$fb6d7286-acab-4b5a-9b6a-2c7127870958$s$, 2, $s$📍Manzanilla Beach$s$);
INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 0, $s$itinerary_with_map$s$, $s${"itineraryId":"fb6d7286-acab-4b5a-9b6a-2c7127870958"}$s$::jsonb),
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 1, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1723","html":"Our first stop was 📌Arima, a town steeped in history and brimming with local charm. We savored the vibrant atmosphere, soaking in the sights and sounds of the bustling market."}$s$::jsonb),
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 2, $s$text$s$, $s${"html":"As we continued west, the sky darkened, and clouds gathered on the horizon. Undeterred, we pressed on towards 📌Sangre Grande. Imagine our surprise when we encountered a bustling market in the center of a roundabout! Local vendors showcased their wares – fresh produce, colorful crafts, and mouthwatering local delicacies. We couldn't resist indulging in the quintessential Trinidadian treat: doubles."}$s$::jsonb),
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 3, $s$text$s$, $s${"html":"With the rain starting to fall, we made our way towards 📌Manzanilla Beach. The road conditions deteriorated rapidly, so we made a quick stop by the beach and then decided to head back to the hotel. Despite the unexpected weather, our journey through the heart of Trinidad was a captivating experience. We encountered the warmth of local communities, savored delicious treats, and witnessed the raw beauty of the island's interior."}$s$::jsonb),
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 4, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1731","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1737","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1728","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1724","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1721","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1725"]}$s$::jsonb);
INSERT INTO "blog_posts" ("id", "country_slug", "post_index", "country", "country_code", "state", "title", "subtitle", "header", "description", "excerpt", "background_image", "tips_cta_copy", "tips_slug", "status", "published_at", "created_at") VALUES ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, $s$trinidad-and-tobago$s$, 4, $s$Trinidad and Tobago$s$, $s$TT$s$, NULL, $s$📍A South Coast Journey, Trinidad 🇹🇹$s$, $s$✨Where natural wonders and cultural treasures await🦩$s$, $s$📍Unveiling La Brea & the Caroni Swamp: A South Coast Journey$s$, $s$Come along with us as we dive into the truly wild side of Trinidad! On this adventure, we'll certainly soak in the local vibe with quick stops at some bustling markets and amazing Indian cultural spots, but our main focus today – the real stars of this trip – are two incredible natural wonders: the mysterious La Brea Pitch Lake and the vibrant Caroni Swamp. We will uncover the secrets of the world's largest natural asphalt lake, where the ground is actually bubbling underneath us. As the sun begins to dip, we'll glide through the mangrove trees of the Caroni Swamp. It's a true paradise for wildlife, building up to that unforgettable moment when thousands of Scarlet Ibises paint the sky in brilliant reds.$s$, $s$Trinidad's Natural Wonders – La Brea & Caroni Swamp Journey 🦩🖤✨$s$, $s$aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1638$s$, $s$💥 Insider Tips: Your Key to an Unforgettable Trip (read more...)$s$, $s$trinidad-and-tobago$s$, $s$published$s$, '2025-08-02T00:00:00.000Z'::timestamptz, '2025-08-02T00:00:00.000Z'::timestamptz);
INSERT INTO "blog_itineraries" ("id", "post_id", "position", "title", "map_embed_url") VALUES
  ($s$3a559e61-29f6-4102-99a9-41a7934cfd6f$s$, $s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 0, $s$South Coast Trinidad$s$, $s$https://www.google.com/maps/embed?pb=!1m64!1m12!1m3!1d251125.70070911525!2d-61.68178347551487!3d10.434341829069302!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!4m49!3e0!4m5!1s0x8c3607d0be7ebb55%3A0x2dd4764afb66c4d6!2sThe%20BRIX%2C%20Autograph%20Collection%2C%20Coblentz%20Avenue%2C%20Port%20of%20Spain%2C%20Trinidad%20and%20Tobago!3m2!1d10.6730318!2d-61.5088929!4m5!1s0x8c35f97bc8e11f6b%3A0xc2c1d38701422f0c!2sChaguanas%2C%20Trinidad%20and%20Tobago!3m2!1d10.5168387!2d-61.4114482!4m5!1s0x8c35f0a801687fd5%3A0xdd0868fb2583c6ac!2sDattatreya%20Mandir%20Temple%2C%20Carapichaima%2C%20Trinidad%20and%20Tobago!3m2!1d10.4755332!2d-61.4315836!4m5!1s0x8c35fa82f493588f%3A0x401667f802b5070!2sSewdass%20Sadhu%20Shiva%20Mandir%20Temple%20in%20the%20Sea%2C%20Temple%2C%20Waterloo%2C%20Trinidad%20and%20Tobago!3m2!1d10.4816922!2d-61.4755472!4m5!1s0x8c358cfa3a951f7d%3A0x1c04ab58c8064b46!2sSan%20Fernando%20Hill%2C%20San%20Fernando%2C%20Trinidad%20and%20Tobago!3m2!1d10.2817507!2d-61.45616!4m5!1s0x8c3596bf9b282857%3A0x8a62a02a86b7e912!2sPitch%20Lake%2C%20New%20Jersey%2C%20Trinidad%20and%20Tobago!3m2!1d10.2325!2d-61.628056!4m5!1s0x8c35fc5028084c8d%3A0x4b88dab8a7a90142!2sCaroni%20Swamp%2C%20Trinidad%20and%20Tobago!3m2!1d10.5913889!2d-61.4552778!4m5!1s0x8c3607d0be7ebb55%3A0x2dd4764afb66c4d6!2sThe%20BRIX%2C%20Autograph%20Collection%2C%20Coblentz%20Avenue%2C%20Port%20of%20Spain%2C%20Trinidad%20and%20Tobago!3m2!1d10.6730318!2d-61.5088929!5e0!3m2!1sen!2sus!4v1754155418943!5m2!1sen!2sus$s$);
